        "tr": {
          "auteur": "Comprendre le Coran",
          "texte": "Rabbiniz, içinizde olanı en iyi bilendir. Eğer siz iyi kişiler olursanız, şunu bilin ki Allah, tövbeye yönelenleri çok bağışlayandır."
        }
