      "ar": "وَقُلْنَا مِن بَعْدِهِ لِبَنِي إِسْرَـٰءِيلَ اسْكُنُواْ الْأَرْضَ فَإِذَا جَاءَ وَعْدُ الْأخِرَةِ جِئْنَا بِكُمْ لَفِيفًا",
